import sys; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, faq_html
calc='''function calc(){const p=num('p'),d=num('d'),L=p-d,ltv=Math.round(L/Math.max(p,1)*1e6)/1e6;const mn=p<=500000?p*.05:p<1500000?25000+(p-500000)*.1:p*.2;
 if(p>=1500000)return big('Insurance not available',cad(0),'Homes of $1.5 million or more need 20% down')+kv([['Minimum down payment',cad(mn,0)]]);
 if(d<mn)return big('Down payment too small',cad(mn-d,0)+' short','Minimum for '+cad(p,0)+' is '+cad(mn,0))+kv([['Minimum down payment',cad(mn,0)],['Your down payment',cad(d,0)]]);
 if(ltv<=.8)return big('No insurance required',cad(0),'You have '+pc(1-ltv)+' down')+kv([['Loan-to-value',pc(ltv)],['Mortgage',cad(L,0)]]);
 let r=ltv<=.85?.028:ltv<=.9?.031:.04;const thirty=$('am').value==='30';if(thirty)r+=.002;const pv=$('pv').value,prem=L*r,tx=pv==='ON'?prem*.08:0,pstRow=pv==='ON'?['Ontario retail sales tax on premium (8%, pay at closing)',cad(tx,0),'neg']:(pv==='QC'||pv==='SK')?['Provincial sales tax on premium','Applies — check your province’s rate (pay at closing)','neg']:['Provincial sales tax on premium','None',''];
 return big('CMHC premium',cad(prem,0),pc(r,2)+' of the '+cad(L,0)+' loan · added to your mortgage')+kv([['Loan-to-value',pc(ltv)],['Premium rate'+(thirty?' (incl. 0.20% for 30 years)':''),pc(r,2)],['Total mortgage incl. premium',cad(L+prem,0),'t'],pstRow,['Minimum down payment',cad(mn,0)]])}'''
FAQ=[
("How much is CMHC insurance on a $500,000 house?","With the minimum 5% down ($25,000) the loan is $475,000 and the premium is 4.00%: $19,000 added to the mortgage. With 10% down ($50,000) it is 3.10% of $450,000 = $13,950."),
("How much is CMHC insurance on a $650,000 home with $50,000 down?","$24,000 (4.00% of the $600,000 loan, loan-to-value 92.3%), plus $1,920 Ontario retail sales tax (8%) paid in cash at closing. With $65,000 down (10%) the premium drops to $18,135 at 3.10%."),
("Can I avoid CMHC insurance?","Yes — put down at least 20% of the purchase price. Then the mortgage is conventional and no default insurance premium is required (lenders may still buy portfolio insurance at their own cost)."),
("Is CMHC insurance paid upfront?","The premium is normally added to the mortgage balance and paid off with it. Only the provincial sales tax on the premium — charged in Ontario (8% retail sales tax), Quebec and Saskatchewan — must be paid at closing; it cannot be added to the loan."),
("What is the minimum down payment in Canada?","5% of the first $500,000 and 10% of the part between $500,000 and $1.5 million: $15,000 on $300,000, $40,000 on $650,000 and $75,000 on $1,000,000. The purchase price must be below $1.5 million for insurance; at $1.5 million or more you need 20%."),
("Who can get a 30-year insured mortgage?","Since December 15, 2024, all first-time homebuyers and all buyers of newly built homes can get insured mortgages with 30-year amortizations. CMHC adds a premium surcharge of 20 basis points (0.20%) for a 30-year amortization.")]
art='''<h2>How CMHC mortgage insurance is calculated</h2>
<p>If your down payment is under 20%, Canadian lenders require mortgage default insurance from CMHC (or a private insurer such as Sagen or Canada Guaranty). The premium is a one-time percentage of the <b>loan amount</b>, set by your <b>loan-to-value ratio (LTV)</b>, and is usually added to the mortgage.</p>
<p>Since December 15, 2024, insured mortgages are available on homes priced below $1.5 million, and all first-time buyers and all buyers of new builds can choose a 30-year amortization.</p>
<p><b>Formula:</b> premium = (price − down payment) × premium rate; LTV = loan ÷ price. Add 0.20% to the rate for a 30-year amortization.</p>
<h3>CMHC premium rates (homeowner loans)</h3>
'''+table(['Loan-to-value','Down payment','Premium (25-year)','Premium (30-year)'],[['Up to 65%','35% or more','0.60% (optional)','—'],['65.01% – 75%','25% – 34.99%','1.70% (optional)','—'],['75.01% – 80%','20% – 24.99%','2.40% (optional)','—'],['80.01% – 85%','15% – 19.99%','2.80%','3.00%'],['85.01% – 90%','10% – 14.99%','3.10%','3.30%'],['90.01% – 95%','5% – 9.99%','4.00%','4.20%'],['90.01% – 95% (non-traditional down payment)','5% – 9.99%','4.50%','4.50% + 0.20%']])+'''
<p class="note">With 20% or more down, insurance is not required for a purchase; the lower rates apply only if insurance is taken anyway. A non-traditional down payment is one not from your own resources (for example certain borrowed funds).</p>
<h3>Minimum down payment and price cap</h3>
'''+table(['Purchase price','Minimum down payment','Example'],[['Up to $500,000','5%','$300,000 → $15,000'],['$500,000 – $1,499,999','5% of first $500,000 + 10% of the rest','$650,000 → $40,000; $1,000,000 → $75,000'],['$1.5 million or more','20% (insurance not available)','$1,600,000 → $320,000']])+'''
<p class="note">The insured-mortgage price cap was raised from $1 million to $1.5 million on December 15, 2024.</p>
<h3>Sales tax on the premium</h3>
<p>Premiums in Ontario, Quebec and Saskatchewan are subject to provincial sales tax, which is payable at closing and cannot be added to the loan amount. In Ontario it is the 8% retail sales tax on insurance premiums; check the current rate with Revenu Québec or Saskatchewan Finance if you buy there. The calculator shows the Ontario amount only.</p>
<h3>Worked examples</h3>
'''+table(['Price','Down payment','Loan','LTV','Rate','Premium','Mortgage incl. premium','Tax at closing'],[['$400,000','$20,000 (5%)','$380,000','95%','4.00%','$15,200','$395,200','$1,216 (ON)'],['$500,000','$50,000 (10%)','$450,000','90%','3.10%','$13,950','$463,950','$1,116 (ON)'],['$650,000','$50,000','$600,000','92.3%','4.00%','$24,000','$624,000','$1,920 (ON)'],['$650,000','$97,500 (15%)','$552,500','85%','2.80%','$15,470','$567,970','$1,238 (ON)'],['$800,000','$55,000 (min.)','$745,000','93.1%','4.20% (30 yr)','$31,290','$776,290','$0 (AB/BC)'],['$1,000,000','$100,000 (10%)','$900,000','90%','3.30% (30 yr)','$29,700','$929,700','PST applies (QC)']])+'''
<h3>Tips and common mistakes</h3>
<ul><li><b>Watch the tier edges:</b> going from 9.9% to 10% down moves you from 4.00% to 3.10% — on a $500,000 home the premium falls from about $18,000 to $13,950.</li>
<li><b>Premium is on the loan, not the price</b>, and it accrues interest because it is part of the mortgage.</li>
<li><b>Bring cash for the tax</b> in Ontario (8% of the premium), Quebec and Saskatchewan, on top of the down payment and closing costs.</li>
<li><b>30 years costs more:</b> the 0.20% surcharge plus more interest over the longer term; it lowers the monthly payment, not the total cost.</li>
<li><b>Price of $1.5 million or more</b> cannot be insured, so 20% down is mandatory.</li></ul>
'''+faq_html(FAQ)+'''
<p class="note">Sources (checked 22 Nov 2026): <a href="https://www.cmhc-schl.gc.ca/consumers/home-buying/mortgage-loan-insurance-for-consumers/cmhc-mortgage-loan-insurance-cost" rel="nofollow">CMHC – Mortgage loan insurance cost</a> (premium table, PST in QC/ON/SK); <a href="https://www.cmhc-schl.gc.ca/media-newsroom/notices/2024/cmhc-revises-homeowner-mortgage-loan-insurance-premiums" rel="nofollow">CMHC – revised homeowner premiums</a> (20 basis point surcharge for 30-year amortization); <a href="https://www.canada.ca/en/department-finance/news/2024/12/boldest-mortgage-reforms-in-decades-come-into-force-today.html" rel="nofollow">Department of Finance – reforms in force December 15, 2024</a> ($1.5 million cap, 30-year amortization); <a href="https://www.cmhc-schl.gc.ca/consumers/home-buying/mortgage-loan-insurance-for-consumers/what-are-the-general-requirements-to-qualify-for-homeowner-mortgage-loan-insurance" rel="nofollow">CMHC – requirements for homeowner insurance</a> (minimum down payment, price below $1.5 million); <a href="https://www.ontario.ca/document/retail-sales-tax/insurance-and-benefits-plans" rel="nofollow">Ontario – RST on insurance</a> (8%). Examples calculated with the calculator on this page. Not financial advice.</p>'''
print(build('/ca/cmhc-insurance-calculator.html','CMHC Insurance Calculator 2026 – Premium, Minimum Down Payment & PST',
 'Calculate CMHC mortgage insurance in 2026: 2.80%–4.00% of the loan by down payment, +0.20% for 30 years, minimum down payment, $1.5M cap and Ontario 8% tax at closing.',art,FAQ,calc=calc))
